\caption{\textproc{EvaluatePhiGrad}}
\label{alg:evaluate_phi_grad}
\begin{algorithmic}[1]
\Require $A\in\mathbb{S}^n_{++}$, $x\in\Omega_x$
\Ensure $\Phi$, the gradient $g=\nabla\Phi(x)\in\mathbb{R}^m$, and $B=M^{-1}$
\State $C\gets\sum_{k=1}^m x_k D_k$, \; $M\gets A-C$
\State Factorize $M$, \; $\Phi\gets-\log\det(M)$, \; $B\gets M^{-1}$
\For{$k=1$ \textbf{to} $m$}
 \State $g_k\gets\mathrm{tr}(BD_k)$
\EndFor
\State \Return $\Phi$, $g$, $B$
\end{algorithmic}

\caption{\textproc{HvProduct}}
\label{alg:hv_product}
\begin{algorithmic}[1]
\Require Basis $\{D_k\}_{k=1}^m$, $B\in\mathbb{S}^n_{++}$, a vector $p\in\mathbb{R}^m$
\Ensure $q=H(x)p\in\mathbb{R}^m$
\State $D(p)\gets\sum_{\ell=1}^m p_\ell D_\ell$
\State $Y\gets B\,D(p)\,B$
\For{$k=1$ \textbf{to} $m$}
 \State $q_k\gets\mathrm{tr}(D_kY)$
\EndFor
\State \Return $q$
\end{algorithmic}
